content.query:
GuardrailsDebugMetrics_CL
| where TimeGenerated {TimeRange}
| where ModuleName_s != "MainRunbook"
| where ErrorCount_d > 0 or isnotempty(Errors_s)
{%if ModuleName != "value::all"%}
| where ModuleName_s == '{ModuleName}'
{%endif%}
| extend ErrorDetails = iff(isnotempty(Errors_s), Errors_s, "No error details available")
| project TimeGenerated, ModuleName_s, ControlName_s, ErrorCount_d, ErrorDetails
| order by TimeGenerated desc

GuardrailsDebugMetrics_CL
| where TimeGenerated {TimeRange}
| where ModuleName_s != "MainRunbook"
{%if ModuleName != "value::all"%}
| where ModuleName_s == '{ModuleName}'
{%endif%}
| extend ExecutionTime = todouble(ExecutionTimeSeconds_d)
| summarize AvgExecutionTime = avg(ExecutionTime) by ModuleName_s, bin(TimeGenerated, 1h)
| render timechart

GuardrailsDebugMetrics_CL
| where TimeGenerated {TimeRange}
| where ModuleName_s != "MainRunbook"
{%if ModuleName != "value::all"%}
| where ModuleName_s == '{ModuleName}'
{%endif%}
| summarize ErrorCount = sumif(toint(ErrorCount_d), toint(ErrorCount_d) > 0) by ControlName_s
| where ErrorCount > 0
| render columnchart
